  "implementation": "def solve(case):
    import math

    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    for key in ('edges', 'communities', 'resolution'):
        if key not in case:
            raise ValueError(f'Missing required field: {key}')

    edges = case['edges']
    communities_input = case['communities']
    resolution = case['resolution']

    # Validate types
    if not isinstance(edges, list):
        raise ValueError('edges must be a list')
    if not isinstance(communities_input, dict):
        raise ValueError('communities must be a dict')
    if not isinstance(resolution, (int, float)):
        raise ValueError('resolution must be a number')

    # Build adjacency and degree
    adjacency = {}
    degree = {}
    total_weight = 0.0
    for edge in edges:
        if not isinstance(edge, list) or len(edge) != 3:
            raise ValueError('Each edge must be a list of [u, v, weight]')
        u, v, w = edge
        if not isinstance(u, str) or not isinstance(v, str) or not isinstance(w, (int, float)):
            raise ValueError('Edge endpoints must be strings and weight numeric')
        if w < 0:
            raise ValueError('Edge weight must be non-negative')
        total_weight += w
        adjacency.setdefault(u, []).append((v, w))
        adjacency.setdefault(v, []).append((u, w))
        degree[u] = degree.get(u, 0.0) + w
        degree[v] = degree.get(v, 0.0) + w

    # Copy communities to avoid mutation
    communities = dict(communities_input)
    # Validate all nodes in communities are present in adjacency (or at least have degree)
    for node in communities:
        if node not in degree:
            # isolated node, degree 0
            degree[node] = 0.0
            adjacency.setdefault(node, [])

    # Precompute community aggregates
    sum_tot = {}
    for node, comm in communities.items():
        sum_tot[comm] = sum_tot.get(comm, 0.0) + degree[node]

    # sum_in: internal edge weight in each community
    sum_in = {}
    for u, v, w in edges:
        if communities.get(u) == communities.get(v):
            comm = communities[u]
            sum_in[comm] = sum_in.get(comm, 0.0) + w

    # Total weight m (sum of weights)
    m = total_weight
    gamma = resolution

    # Sorted node order (stable)
    nodes = sorted(communities.keys())

    moves = []

    for node in nodes:
        cur_comm = communities[node]
        k_i = degree[node]
        if k_i == 0:
            continue  # isolated node, cannot move

        # Gather neighbor communities and weights to each
        nc_weights = {}
        for nb, w in adjacency[node]:
            nb_comm = communities[nb]
            nc_weights[nb_comm] = nc_weights.get(nb_comm, 0.0) + w
        # Ensure current community is present (even if zero)
        if cur_comm not in nc_weights:
            nc_weights[cur_comm] = 0.0

        w_in_cur = nc_weights[cur_comm]
        sum_tot_cur = sum_tot.get(cur_comm, 0.0)

        best_gain = 0.0
        best_comm = cur_comm

        for cand_comm, w_in_cand in nc_weights.items():
            sum_tot_cand = sum_tot.get(cand_comm, 0.0)
            # Compute deltaQ
            # deltaQ = (w_in_cand - w_in_cur)/m - gamma * (k_i * (sum_tot_cand - sum_tot_cur) + k_i**2) / (2 * m**2)
            delta = (w_in_cand - w_in_cur) / m - gamma * (k_i * (sum_tot_cand - sum_tot_cur) + k_i * k_i) / (2.0 * m * m)
            if delta > best_gain + 1e-12:
                best_gain = delta
                best_comm = cand_comm
            elif abs(delta - best_gain) <= 1e-12:
                # tie-breaking by lexical community ID
                if cand_comm < best_comm:
                    best_gain = delta
                    best_comm = cand_comm

        if best_comm != cur_comm and best_gain > 1e-12:
            # Record move
            moves.append({'from': cur_comm, 'node': node, 'to': best_comm})

            # Update communities
            communities[node] = best_comm

            # Update sum_tot
            sum_tot[cur_comm] = sum_tot.get(cur_comm, 0.0) - k_i
            sum_tot[best_comm] = sum_tot.get(best_comm, 0.0) + k_i

            # Update sum_in for edges incident to node
            for nb, w in adjacency[node]:
                nb_comm = communities[nb]
                if nb_comm == cur_comm:
                    sum_in[cur_comm] = sum_in.get(cur_comm, 0.0) - w
                elif nb_comm == best_comm:
                    sum_in[best_comm] = sum_in.get(best_comm, 0.0) + w

    result = {
        'communities': communities,
        'moves': moves
    }
    return result"
